  ) AS v(source_id, page_index, text)
  JOIN books b
    ON b.source_platform = 'african_storybook' AND b.source_id = v.source_id
ON CONFLICT (book_id, page_index) DO NOTHING;

-- ───────── [적재검증] 트랜잭션 안 ─────────
-- (c) 적재 후 행 수 — 기대 465
SELECT count(*) AS rows_after FROM book_text bt
  JOIN books b ON b.id = bt.book_id
  WHERE b.source_platform='african_storybook' AND b.source_id IN ('36851', '36888', '36895', '36897', '36898', '36899', '36904', '36908', '36909', '36912', '36914', '36918', '36926', '36927', '36931', '36933', '36945', '36987', '36993', '36998', '37009', '37033', '37036', '37096', '37129', '37137', '37155', '37186', '37208', '37218', '37281', '37309', '37311', '37350', '37352', '37353', '37385', '37457', '37488', '37496', '37501', '37515', '37541', '37552', '37559', '37579', '37629', '37753');
-- (d) 조인 실패로 누락된 source_id — 기대 0행
SELECT v.source_id FROM (VALUES ('36851'), ('36888'), ('36895'), ('36897'), ('36898'), ('36899'), ('36904'), ('36908'), ('36909'), ('36912'), ('36914'), ('36918'), ('36926'), ('36927'), ('36931'), ('36933'), ('36945'), ('36987'), ('36993'), ('36998'), ('37009'), ('37033'), ('37036'), ('37096'), ('37129'), ('37137'), ('37155'), ('37186'), ('37208'), ('37218'), ('37281'), ('37309'), ('37311'), ('37350'), ('37352'), ('37353'), ('37385'), ('37457'), ('37488'), ('37496'), ('37501'), ('37515'), ('37541'), ('37552'), ('37559'), ('37579'), ('37629'), ('37753')) AS v(source_id)
  WHERE NOT EXISTS (SELECT 1 FROM books b
     WHERE b.source_platform='african_storybook' AND b.source_id=v.source_id);
-- (e) source 라벨 분포 — 기대 manifest_txt_v1 1종 / 465행
SELECT bt.source, count(*) FROM book_text bt JOIN books b ON b.id=bt.book_id
  WHERE b.source_platform='african_storybook' AND b.source_id IN ('36851', '36888', '36895', '36897', '36898', '36899', '36904', '36908', '36909', '36912', '36914', '36918', '36926', '36927', '36931', '36933', '36945', '36987', '36993', '36998', '37009', '37033', '37036', '37096', '37129', '37137', '37155', '37186', '37208', '37218', '37281', '37309', '37311', '37350', '37352', '37353', '37385', '37457', '37488', '37496', '37501', '37515', '37541', '37552', '37559', '37579', '37629', '37753')
  GROUP BY bt.source;
-- (f) page_index 축 검증 — 권마다 0부터 연속이어야 한다. 기대 0행(위반 없음)
SELECT b.source_id, min(bt.page_index) AS mn, max(bt.page_index) AS mx, count(*) AS n
  FROM book_text bt JOIN books b ON b.id=bt.book_id
  WHERE b.source_platform='african_storybook' AND b.source_id IN ('36851', '36888', '36895', '36897', '36898', '36899', '36904', '36908', '36909', '36912', '36914', '36918', '36926', '36927', '36931', '36933', '36945', '36987', '36993', '36998', '37009', '37033', '37036', '37096', '37129', '37137', '37155', '37186', '37208', '37218', '37281', '37309', '37311', '37350', '37352', '37353', '37385', '37457', '37488', '37496', '37501', '37515', '37541', '37552', '37559', '37579', '37629', '37753')
  GROUP BY b.source_id HAVING min(bt.page_index) <> 0 OR max(bt.page_index) <> count(*)-1;
-- (g) 빈 면 행 수 — 기대 0 (D7: 빈 면도 text='' 로 적재)
SELECT count(*) AS empty_rows FROM book_text bt JOIN books b ON b.id=bt.book_id
  WHERE b.source_platform='african_storybook' AND b.source_id IN ('36851', '36888', '36895', '36897', '36898', '36899', '36904', '36908', '36909', '36912', '36914', '36918', '36926', '36927', '36931', '36933', '36945', '36987', '36993', '36998', '37009', '37033', '37036', '37096', '37129', '37137', '37155', '37186', '37208', '37218', '37281', '37309', '37311', '37350', '37352', '37353', '37385', '37457', '37488', '37496', '37501', '37515', '37541', '37552', '37559', '37579', '37629', '37753') AND bt.text = '';

-- ───────── [종료] ─────────
-- (c)~(g)가 전부 기대값과 일치하면 아래 ROLLBACK; 을 COMMIT; 으로 바꿔 타이핑한다.
ROLLBACK;
